type HashRing struct {
  vnodes   int
  ring     []uint32          // Sorted token slice
  nodeMap  map[uint32]string // Token -> Physical Node ID
  mu       sync.RWMutex
}

func (h *HashRing) GetNode(key string) string {
  h.mu.RLock()
  defer h.mu.RUnlock()
  if len(h.ring) == 0 { return "" }

  hash := fnv32(key)
  // Binary search to find clockwise successor in O(log(N * vnodes))
  idx := sort.Search(len(h.ring), func(i int) bool {
    return h.ring[i] >= hash
  })
  // Wrap around ring if hash exceeds largest token
  if idx == len(h.ring) { idx = 0 }
  return h.nodeMap[h.ring[idx]]
}
